import { emitPageLink } from "../pageLink.js";
import { positionalArgs } from "../parseArgs.js";
export async function runStartDataset(_platform, _pluginVersion) {
    const args = positionalArgs([
        { name: "functionKey", description: "Trace function key." },
        { name: "datasetId", format: "uuid", description: "Dataset ID." },
    ], process.argv, { description: "Print a link to the page and exit." });
    emitPageLink(`/trace-functions/${encodeURIComponent(args[0])}/datasets/${encodeURIComponent(args[1])}`);
}
